// ===========================================================================
// LINKA Catalog seed  (MongoDB)  ->  database: LinkaCatalogDb
// REAL product photos: main image + gallery angles per product.
//   electronics / furniture / shoes / clothing / kitchen -> DummyJSON CDN
//   books -> Open Library covers ; monitors/headphones/chocolate/produce -> stock photos
//
// HOW TO RUN:
//   mongosh "mongodb://localhost:27017/LinkaCatalogDb" linka_seed.js
//
// Categories are matched by NAME (existing ones reused, no duplicates).
// Re-running ADDS products again, so clear first if you want a fresh set.
// ===========================================================================

db = db.getSiblingDB("LinkaCatalogDb");

// --- OPTIONAL: wipe catalog before seeding (uncomment the 4 lines) ----------
 //db.Products.deleteMany({});
 //db.ProductDetails.deleteMany({});
 //db.ProductImages.deleteMany({});
 //db.Categories.deleteMany({});

function hex(oid){ return oid.toHexString ? oid.toHexString() : (oid.str || String(oid)); }

// 1) Ensure categories exist, capture their _id ------------------------------
var categoryImages = {
  "Computers": "https://cdn.dummyjson.com/product-images/laptops/apple-macbook-pro-14-inch-space-grey/1.webp",
  "Clothing": "https://cdn.dummyjson.com/product-images/mens-shirts/man-plaid-shirt/1.webp",
  "Furniture": "https://cdn.dummyjson.com/product-images/furniture/annibale-colombo-sofa/1.webp",
  "Books": "https://covers.openlibrary.org/b/isbn/9780547928227-L.jpg",
  "Phones": "https://cdn.dummyjson.com/product-images/smartphones/iphone-13-pro/1.webp",
  "Monitors": "https://loremflickr.com/700/700/monitor?lock=999",
  "Headphones": "https://loremflickr.com/700/700/headphones?lock=999",
  "Shoes": "https://cdn.dummyjson.com/product-images/mens-shoes/nike-air-jordan-1-red-and-black/1.webp",
  "Kitchen Utensils": "https://cdn.dummyjson.com/product-images/kitchen-accessories/boxed-blender/1.webp",
  "Vegetables": "https://cdn.dummyjson.com/product-images/groceries/cucumber/1.webp",
  "Fruits": "https://cdn.dummyjson.com/product-images/groceries/apple/1.webp",
  "Chocolates": "https://loremflickr.com/700/700/chocolate?lock=999"
};
var catIds = {};
Object.keys(categoryImages).forEach(function(name){
  var existing = db.Categories.findOne({ CategoryName: name });
  if (existing) { catIds[name] = existing._id; }
  else {
    var r = db.Categories.insertOne({ CategoryName: name, ImageUrl: categoryImages[name] });
    catIds[name] = r.insertedId;
  }
});
print("Categories ready: " + Object.keys(catIds).length);

function randomStock() {
    return Math.floor(Math.random() * 16) + 5;
}

