var inserted = 0;
products.forEach(function(p){
  var oid = new ObjectId();
  db.Products.insertOne({
    _id: oid,
    ProductName: p.ProductName,
    ProductPrice: NumberDecimal(p.ProductPrice),
    DiscountRate: NumberDecimal(p.DiscountRate),
    ProductImageUrl: p.ProductImageUrl,
    ProductDescription: p.ProductDescription,
      CategoryId: catIds[p.cat],
      StockCount: randomStock(),
      IsFeatured: false,
      FeaturedOrder: 0

  });
  var pid = hex(oid);
  db.ProductDetails.insertOne({
    ProductDescription: p.ProductDescription,
    ProductInfo: p.ProductInfo,
    ProductId: pid
  });
  db.ProductImages.insertOne({ Images: p.Images, ProductId: pid });
  inserted++;
});

print("Inserted products: " + inserted);
print("Totals -> Categories: " + db.Categories.countDocuments({}) +
      ", Products: " + db.Products.countDocuments({}) +
      ", ProductDetails: " + db.ProductDetails.countDocuments({}) +
      ", ProductImages: " + db.ProductImages.countDocuments({}));
